{
  "positionId": "P03",
  "interviews": [
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "처방 용량에 의문이 있을 때 투약을 그대로 진행하지 않고, 확인 전까지 중단할 수 있는 판단 기준을 검증한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "수술 후 환자의 진통제 처방 용량이 평소의 두 배로 입력된 상황이었다.",
          "task": "의심스러운 처방을 확인하지 않은 채 투약하지 않도록 투약 진행 여부를 판단해야 했다.",
          "action": "진통제 용량의 차이를 단순히 수용하지 않고 투약을 보류할 대상으로 판단한 기준과, 담당의 확인이 필요하다고 본 이유를 설명한다.",
          "result": "투약을 멈추고 담당의에게 확인한 결과 처방 입력 오류였음이 확인되어, 판단 기준이 환자에게 잘못된 용량을 투여하지 않는 데 연결되었다."
        },
        "expectedEvidence": [
          "진통제 처방 용량의 적절성이 확인되지 않으면 투약을 보류한다는 구체적인 판단 기준",
          "평소 용량의 두 배라는 차이를 확인이 필요한 신호로 본 이유",
          "투약을 멈추고 담당의에게 확인하여 입력 오류를 확인한 결과"
        ]
      },
      "question": "수술 후 환자의 진통제 처방 용량이 평소의 두 배로 들어왔을 때, 처방대로 투약할지 멈추고 담당의에게 확인할지를 결정한 기준은 무엇이었나요?",
      "answerTip": "당시 본인이 했던 판단을 중심으로 차분하게 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "진통제 처방 용량의 적절성이 확인되지 않으면 투약을 보류한다는 기준을 명시하고, 평소의 두 배인 용량을 그대로 투여하지 않은 이유를 설명한다.",
            "진통제 투약을 멈추고 담당의에게 확인한 결과 입력 오류였다는 사실을 판단 기준과 연결해 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "진통제 처방이 의심스러우면 투약을 멈추고 확인한다는 기준은 제시하지만, 해당 용량 차이를 확인 대상으로 판단한 이유는 설명하지 못한다."
          ]
        },
        "poor": {
          "criteria": [
            "진통제 투약을 진행하거나 보류하는 판단 기준을 제시하지 못하고 일반적인 투약 경험만 이야기하거나, 의심스러운 용량도 확인 없이 처방대로 투여한다고 답한다."
          ]
        }
      }
    },
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "관찰된 환자 상태와 관련 정보를 다음 근무자가 놓치지 않도록 인수인계 항목으로 연결하는 선정 기준을 검증한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "수술 후 첫 보행 환자의 낙상이 근무 교대 시간대에 몰려 있어 인수인계 체크리스트를 개선한 상황이었다.",
          "task": "교대 후에도 환자 상태와 관련된 주의사항이 빠지지 않도록 전달할 항목을 정해야 했다.",
          "action": "진통제 투여 시각과 보행 보조 여부를 인수인계 항목으로 정한 기준을 설명하고, 해당 정보가 다음 근무자의 환자 상태 파악에 필요한 이유를 연결한다.",
          "result": "선정한 항목을 통해 다음 근무자가 어떤 환자 상태 관련 정보를 놓치지 않게 되었는지 설명한다."
        },
        "expectedEvidence": [
          "다음 근무자의 환자 상태 파악에 필요한 정보를 인수인계 항목으로 선정한 구체적인 기준",
          "근무 교대 시간대의 수술 후 첫 보행 환자 낙상과 선정 기준의 연결",
          "진통제 투여 시각과 보행 보조 여부가 다음 근무자에게 전달되어야 하는 이유"
        ]
      },
      "question": "인수인계 체크리스트에 진통제 투여 시각과 보행 보조 여부를 추가했던 경험에서, 환자 상태 정보를 다음 근무자에게 빠짐없이 전달할 인수인계 항목을 정한 기준은 무엇이었나요?",
      "answerTip": "당시 경험에서 본인이 생각했던 내용을 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "인수인계 항목 선정 기준을 다음 근무자가 환자 상태와 주의사항을 빠짐없이 파악하는 데 필요한 정보로 구체화한다.",
            "진통제 투여 시각과 보행 보조 여부를 선정한 이유를 교대 시간대의 첫 보행 환자 낙상 상황과 연결해 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "환자 상태와 관련해 중요한 정보를 인수인계 항목으로 정했다는 기준과 추가한 항목은 제시하지만, 다음 근무자에게 해당 정보가 필요한 이유는 설명하지 못한다."
          ]
        },
        "poor": {
          "criteria": [
            "환자 상태 정보를 전달할 인수인계 항목의 선정 기준을 제시하지 못하고, 체크리스트 개선 활동의 성과나 참여 사실만 이야기한다."
          ]
        }
      }
    }
  ]
}
